import{arteryStates,tumourState}from './health-models.js?v=20261023-physicscomplete01';
export function buildArtery(g,T,state='narrow',deposit){const s=arteryStates[state]||arteryStates.narrow,d=deposit??s.deposit,lumen=state==='stent'?.78:1-d,mat=(c,e={})=>new T.MeshStandardMaterial({color:c,roughness:.3,metalness:.03,side:T.DoubleSide,...e});function tube(ro,ri,z0,len,color){const shape=new T.Shape();shape.absarc(0,0,ro,Math.PI/3,Math.PI*5/3,false);shape.lineTo(Math.cos(Math.PI*5/3)*ri,Math.sin(Math.PI*5/3)*ri);shape.absarc(0,0,ri,Math.PI*5/3,Math.PI/3,true);shape.closePath();const mesh=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:len,bevelEnabled:false,curveSegments:48}),mat(color));mesh.position.x=-z0;mesh.rotation.y=-Math.PI/2;g.add(mesh);}tube(.92,.76,-2,4,0xc67f73);tube(.75,Math.max(.15,.7*lumen),-1.65,3.3,0xd4ae70);
if(state==='stent'){for(let i=0;i<12;i++){let ring=new T.Mesh(new T.TorusGeometry(.57,.015,8,48),mat(0xb7c8d6,{metalness:.65}));ring.rotation.y=Math.PI/2;ring.position.x=-1.45+i*.26;g.add(ring);}for(let i=0;i<8;i++){let a=i*Math.PI/4,rod=new T.Mesh(new T.CylinderGeometry(.012,.012,3.1,8),mat(0xd7e3e9,{metalness:.65}));rod.rotation.z=Math.PI/2;rod.position.set(0,.57*Math.sin(a),.57*Math.cos(a));g.add(rod);}}
for(let i=0;i<9;i++){let cell=new T.Mesh(new T.SphereGeometry(.13,24,16),mat(0xa9403e));cell.scale.set(1,.45,1);cell.position.set(-1.8+i*.44,Math.sin(i*1.7)*.14,Math.cos(i*1.4)*.12);g.add(cell);}}

export function buildCancer(g,T,kind='benign',step=3){const s=tumourState(kind,step),material=(c,e={})=>new T.MeshStandardMaterial({color:c,roughness:.28,metalness:.03,...e});const base=new T.Mesh(new T.BoxGeometry(3.1,.14,2.3),material(0x526f7d));base.position.set(-.7,-.72,0);g.add(base);for(let i=0;i<s.count;i++){let a=i*2.399,r=.17*Math.sqrt(i),cell=new T.Mesh(new T.SphereGeometry(.24,32,24),material(kind==='normal'?0x8aafb5:0xd88978));cell.position.set(-.8+Math.cos(a)*r,-.33+(i%3)*.19,Math.sin(a)*r);g.add(cell);let nucleus=new T.Mesh(new T.SphereGeometry(.065,16,12),material(0x8f4e4a));nucleus.position.copy(cell.position).add(new T.Vector3(0,.2,.08));g.add(nucleus);}if(!s.invasion){let wall=new T.Mesh(new T.TorusGeometry(1.02,.025,10,80),material(0xe9d5b6));wall.rotation.x=Math.PI/2;wall.position.set(-.8,-.15,0);g.add(wall);}const vessel=new T.Mesh(new T.CylinderGeometry(.18,.18,2.8,32),material(0x9b6262,{transparent:true,opacity:.65}));vessel.rotation.x=Math.PI/2;vessel.position.set(1.2,-.25,0);g.add(vessel);if(s.invasion){let a=new T.Mesh(new T.SphereGeometry(.2,28,20),material(0xd88978));a.position.set(.5,-.25,0);g.add(a);}if(s.inBlood){let a=new T.Mesh(new T.SphereGeometry(.14,28,20),material(0xeec3a6));a.position.set(1.2,-.25,.45);g.add(a);}if(s.secondary)for(let i=0;i<4;i++){let a=new T.Mesh(new T.SphereGeometry(.2,28,20),material(0xd88978));a.position.set(1.85+(i%2)*.3,-.3+Math.floor(i/2)*.25,.8);g.add(a);}}
